import time
from velocity_communicator.rest.query import RestQueryException


class CIFunctions(object):

    def ci_recursive_wait_in_queue(self, res_id, expected_status="ACTIVE", priority_string=None):
        '''
        waits for queued reservation, dynamically increasing reservation duration

        this is good in case some problem in CI test line during reservation, this way if test/env crash during queue
        resources wont be reserved for whatever your original duration of reservation would have been (10 hour
        for example etc)

        also add feature to manipulate queue, if priority string is found in reservation description reservation
        will be immediately canceled, after which can be restarted at the back of the queue
        '''
        self.logger.info(self.get_queue_reason(res_id))
        self.logger.info("recursive_wait_in_queue")
        elapsed_time = 0
        bad_status = ["DECLINED", "FAILED", "CANCELLED", "TERMINATED", "COMPLETED"]
        while True:
            time.sleep(10)
            elapsed_time += 10
            self.logger.info(f"elapsed time: {elapsed_time}")
            reservation_status = self.get_reservation(res_id)
            self.logger.info('Current status {} expected status {}'.format(reservation_status['status'], expected_status))
            if reservation_status['status'] == expected_status:
                self.logger.info(f'Expected Velocity reservation status {expected_status} reached')
                return True, reservation_status
            if reservation_status['status'] in bad_status:
                self.logger.warning('Reservation status is: {}'.format(reservation_status['status']))
                reservation_data = self.get_reservation(res_id)
                fail_reason = reservation_data['failReason']
                try:
                    self.logger.debug(f'{fail_reason}')
                except UnicodeEncodeError:
                    self.logger.debug('failReason contained non-ASCII symbols that are ignored')
                    fail_reason = fail_reason.encode(encoding='ascii', errors='ignore')
                    self.logger.debug(f'{fail_reason}')
                return False, reservation_status
            if priority_string and reservation_status['description'] == priority_string:
                self.logger.info(reservation_status['description'])
                self.logger.info("high priority reservation, adjusting queue by releasing current reservation and "
                                 "making new reservation")
                self.ci_release_reservation(res_id)
                self.logger.info("sleep 60")
                time.sleep(60)
                return True, reservation_status
            if elapsed_time % 290 == 0:
                self.ci_extend_reservation_duration_if_less_than(res_id)
                self.logger.info(self.get_queue_reason(res_id))

    def ci_extend_reservation_duration_if_less_than(self, res_id, time_minutes=15):
        print(f"extend_duration_if_less_than {time_minutes}")
        time_in_seconds = time_minutes * 60
        reservation = self.get_reservation(res_id)
        old_endtime = int(str(reservation['end'])[:-3])
        curr_time = int(time.time())
        diff = old_endtime - curr_time
        res_duration = int(diff / 60)
        diff_to_time = time_in_seconds - res_duration
        if res_duration < time_minutes:
            value = int((old_endtime + time_in_seconds) * 1000)
            ret = self.ci_extend_reservation_by_params(res_id, value)
            self.logger.info(f"return value = {ret}")
        else:
            print(f"diff_to_time = {diff_to_time}, res_duration = {res_duration} minutes")

    def ci_set_remaining_duration_to(self, res_id, time_minutes=60):
        time_seconds = int(time_minutes * 60)
        curr_time = int(time.time()) + 1
        value = int((curr_time + time_seconds) * 1000)
        ret = self.ci_extend_reservation_by_params(res_id, value)
        self.logger.info(ret)

    def ci_extend_reservation_by(self, res_id, seconds):
        reservation = self.get_reservation(res_id)
        new_endtime = int(str(reservation['end']) + seconds)
        ret = self.ci_extend_reservation_by_params(res_id, new_endtime)
        self.logger.info("extend_reservation_by")
        self.logger.info(f"return value = {ret}")

    def ci_extend_reservation_by_params(self, reservation_id, endtime, **kwargs):
        dobject = {
            "id": reservation_id,
            "end": endtime
        }
        for key in kwargs:
            dobject[key] = kwargs[key]
        return self.update_reservation(body=dobject, reservation_id=reservation_id)

    def ci_activate_deferred_resource_from_reservation(self, reservation_id,
                                                       resource_activation_ids=[],
                                                       resource_name=[],
                                                       callback_url=None):
        """
        Activate deferred device from reservation. Need either list of
        resource activation id's
        or list of device names. Not both. Activation id is not same as
        inventory id. Activation id
        is individual for each reservation and can be found searching
        deferred devices from
        reservation and using value of the ID key from the information of
        the desired device.

        Returns dictionary of status (expected ACTIVE), devices (names
        and individual statuses) and result of API requests.

        :param reservation_id: ID of the reservation
        :type reservation_id: str
        :param resource_activation_ids: List of reasource activation ids.
        :type resource_activation_ids: List[str]
        :param resource_name: List of reasource names.
        :type resource_name: List[str]
        :return: {status, devices, result}
        :rtype: dictionary

        """
        output = {}
        if resource_name != []:
            resource_activation_ids = self._get_activation_id_list(
                reservation_id=reservation_id, resource_name=resource_name)
        if callback_url == None:
            body = {
                "resourcesIds": resource_activation_ids
            }
        else:
            body = {
                "resourcesIds": resource_activation_ids,
                "callbackURL": callback_url
            }
        counter = 0
        while True:
            result = self.activate_deferred_resource(reservation_id=reservation_id,
                                                     body=body)
            self.logger.info(self.get_queue_reason(reservation_id))
            status = self.ci_wait_deferred_devices_recursive(
                reservation_id=reservation_id,
                resource_activation_ids=resource_activation_ids,
                status="ACTIVE")
            if not status:
                counter += 1
                if counter < 5:
                    self.logger.info("Deferred activation failed, wait and try again")
                    time.sleep(5)
                    continue
                else:
                    raise Exception("deferred activaiton failed 5 times, check topology and velocity messages")
            if "status" in result:
                output["status"] = result["status"]
            else:
                output["status"] = list(status.values())[0]
            output["devices"] = status
            output["result"] = result
            return output

    def ci_wait_deferred_devices_recursive(self, reservation_id, resource_activation_ids, status):
        device_status = {}
        elapsed_time = 0
        bad_reservation_status = ["DECLINED", "FAILED", "CANCELLED", "TERMINATED", "COMPLETED"]
        bad_status = ["ACTIVATION_FAILED", 'INACTIVE', "DEACTIVATION_FAILED"]
        while True:
            time.sleep(10)
            elapsed_time += 10
            self.logger.info(f"elapsed time: {elapsed_time}")
            deferred_devices_in_reservation = self.get_deferred_devices_from_reservation(reservation_id=reservation_id)
            deferred_device = next(
                (item for item in deferred_devices_in_reservation if
                 item['id'] == resource_activation_ids[0]), None)
            if deferred_device["status"] != status:
                self.logger.info('Deferred device status: {}. Waiting status: {}'
                                 .format(deferred_device["status"], status))
            else:
                for device in deferred_devices_in_reservation:
                    if device["id"] in resource_activation_ids:
                        device_status[device["name"]] = device["status"]
                return device_status
            if deferred_device["status"] in bad_status:
                return False
            if elapsed_time % 290 == 0:
                self.logger.info(self.get_queue_reason(reservation_id))
                reservation_status = self.get_reservation(reservation_id)
                if reservation_status['status'] in bad_reservation_status:
                    self.logger.warning('Reservation status is: {}'.format(reservation_status['status']))
                    fail_reason = reservation_status['failReason']
                    try:
                        self.logger.debug('{}'.format(fail_reason))
                    except UnicodeEncodeError:
                        self.logger.debug('failReason contained non-ASCII symbols that are ignored')
                        self.logger.debug('{}'.format(fail_reason.encode(encoding='ascii', errors='ignore')))
                    raise RestQueryException(fail_reason)
                self.ci_extend_reservation_duration_if_less_than(reservation_id)

    def ci_release_deferred_resource_from_reservation(self, reservation_id,
                                                      resource_activation_ids=[],
                                                      resource_name=[],
                                                      callback_url=None):
        """
        Release deferred device from reservation. Need either list of
        resource activation id's
        or list of device names. Not both. Activation id is not same as
        inventory id. Activation id
        is individual for each reservation and can be found searching
        deferred devices from
        reservation and using value of the ID key from the information of
        the desired device.

        Returns dictionary of status, devices (names
        and individual statuses) and result of API requests.

        :param reservation_id: ID of the reservation
        :type reservation_id: str
        :param resource_activation_ids: List of reasource activation ids.
        :type resource_activation_ids: List[str]
        :param resource_name: List of reasource names.
        :type resource_name: List[str]
        :return: {status, devices, result}
        :rtype: dictionary

        """
        output = {}
        if resource_name != []:
            resource_activation_ids = self._get_activation_id_list(
                reservation_id=reservation_id, resource_name=resource_name)
        if callback_url == None:
            body = {
                "resourcesIds": resource_activation_ids
            }
        else:
            body = {
                "resourcesIds": resource_activation_ids,
                "callbackURL": callback_url
            }
        result = self.release_deferred_resource(reservation_id=reservation_id,
                                                body=body)
        status = self.ci_wait_deferred_devices_recursive(
            reservation_id=reservation_id,
            resource_activation_ids=resource_activation_ids, status="INACTIVE")
        if "status" in result:
            output["status"] = result["status"]
        else:
            output["status"] = list(status.values())[0]
        output["devices"] = status
        output["result"] = result
        return output

    def ci_release_reservation(self, reservation_id, status_to_wait_for='COMPLETED'):
        """
        Releases reservation with reservation ID.

        If succeded, returns is_status_reached True and "COMPLETED" status.

        :param reservation_id: ID of the reservation to be released
        :type reservation_id: str
        :param status_to_wait_for: Status from Velocity to wait for to
         ensure release of reservation was successful
        :type status_to_wait_for: str
        :return: is_status_reached, status
        :rtype: Tuple[bool, str]
        :raises: ReleaseNotCompletedException: If reservation release status
         fails to match requested status.
        """
        response = self.perform_reservation_action(reservation_id, type="teardown")
        if response:
            try:
                if response["errorId"] == "RESERVATION_NOT_FOUND":
                    return False, response["errorId"]
                elif response["errorId"] == "RESERVATION_IS_NOT_ACTIVE":
                    time.sleep(5)
                    status = self.get_reservation_status(reservation_id)
                    if status["status"] in ["QUEUED", "SCHEDULED"]:
                        response = self.perform_reservation_action(reservation_id, type="cancel")
                        status_to_wait_for = 'CANCELLED'
                        self.logger.info(f"response: {response}")
                    else:
                        return False, response["errorId"]
                else:
                    raise RestQueryException(status_to_wait_for,
                                             '{}-{}'.format(
                                                 response["errorId"],
                                                 response["message"]))
            except KeyError:
                pass
        is_status_reached, status = self.ci_wait_until_status(
            res_id=reservation_id, expected_status=status_to_wait_for,
            wait_time=300)
        if not is_status_reached:
            raise RestQueryException(status_to_wait_for)
        return is_status_reached, status

    def ci_wait_until_status(self, res_id, expected_status='ACTIVE', wait_time=300):
        started_waiting = time.time()
        bad_status = ["DECLINED", "FAILED", "CANCELLED", "TERMINATED", "COMPLETED"]
        self.logger.info(f'Waiting for reservation to reach {expected_status} state for maximum of {wait_time} seconds')
        while time.time() < started_waiting + wait_time:
            time.sleep(10)
            reservation_status = self.get_reservation(res_id)
            self.logger.info('Current status {}'.format(reservation_status['status']))
            if reservation_status['status'] == expected_status:
                self.logger.info(f'Expected Velocity reservation status {expected_status} reached')
                return True, reservation_status['status']
            if reservation_status['status'] in bad_status:
                self.logger.warning('Reservation status is: {}'.format(reservation_status['status']))
                reservation_data = self.get_reservation(res_id)
                fail_reason = reservation_data['failReason']
                try:
                    self.logger.debug('{}'.format(fail_reason))
                except UnicodeEncodeError:
                    self.logger.debug(
                        'failReason contained non-ASCII symbols that are '
                        'ignored')
                    self.logger.debug('{}'.format(
                        fail_reason.encode(encoding='ascii', errors='ignore')))
                return False, reservation_status['status']
        self.logger.info(f'Timeout while waiting for reservation to reach {expected_status}')
        reservation_status = "failed_due_to_timeout"
        return False, reservation_status

    def ci_get_device_ports_name_and_inventroy_id(self, device_name):
        ports_info = {}
        device = self.get_devices(filter=f'name::{device_name}')
        if device["devices"] == []:
            return "NO_DEVICE"
        ports = self.get_device_ports(device_id=device["devices"][0]["id"], limit=200)
        for port in ports["ports"]:
            ports_info[port["name"]] = port["id"]
        return ports_info
